from pathlib import Path
import json
ids=['DEV-PRED-CONT-NEXT-7b8846e9669d7c05da627cc7','DEV-PRED-CONT-NEXT-50178168cc8b3a8e879648db','DEV-PRED-CONT-NEXT-9d4707f66ec86d580643a52c']
roots=[Path.home()/'.local/state/prediction-project-executor',Path.home()/'.local/share/prediction-project-executor']
rows=[]
for tid in ids:
    hits=[]
    for root in roots:
        if root.exists():
            for p in root.rglob('*'):
                if p.is_file() and tid in p.name:
                    hits.append(p)
    vals=[]
    for p in hits[:24]:
        try: txt=p.read_text(errors='replace')
        except Exception: continue
        vals.append(str(p)+':'+txt[:5000].replace('\n',' ').replace('|','/'))
    rows.append(tid+'=>'+' || '.join(vals))
print('ERROR_CLASS=NORMALIZE_CHAIN_FINAL_STATUS')
print('ERROR='+' ### '.join(rows)[:14000])
raise SystemExit(1)
